function escAdmin(v){return String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));}document.addEventListener('DOMContentLoaded',load);async function load(){const el=document.getElementById('contactos-real');try{const rows=await apiFetch('/operacoes/admin/contactos');el.innerHTML=rows.length?rows.map(c=>'<div class="item-conversa"><span><strong>'+escAdmin(c.nome||c.email)+'</strong> — '+escAdmin(c.assunto||'Contacto')+'<br><small>'+escAdmin(c.mensagem||'')+'</small></span><span><select onchange="estadoContacto('+c.id+',this.value)"><option value="novo" '+(c.estado==='novo'?'selected':'')+'>novo</option><option value="em_analise" '+(c.estado==='em_analise'?'selected':'')+'>em análise</option><option value="respondido" '+(c.estado==='respondido'?'selected':'')+'>respondido</option><option value="fechado" '+(c.estado==='fechado'?'selected':'')+'>fechado</option></select></span></div>').join(''):'<div class="item-conversa">Ainda não existem contactos.</div>'}catch(e){el.textContent='Erro ao carregar contactos: '+e.message}}async function estadoContacto(id,estado){try{await apiFetch('/operacoes/admin/contactos/'+id,{method:'PUT',body:JSON.stringify({estado})})}catch(e){alert(e.message);load()}}
